<?php
require '../includes/functions.php';
$u=require_role('citizen'); verify_csrf(); $pdo=db(); $id=(int)($_GET['id']??$_POST['id']??0);
if($_SERVER['REQUEST_METHOD']==='POST' && ($_POST['action']??'')==='reopen'){
 $reason=trim($_POST['reason']??'');$q=$pdo->prepare('SELECT status,tracking_number,department_id FROM grievances WHERE id=? AND citizen_id=?');$q->execute([$id,$u['id']]);$item=$q->fetch();
 if(!$item||$item['status']!=='Resolved'||mb_strlen($reason)<10){flash('A resolved grievance and a reason of at least 10 characters are required to request reopening.');redirect('citizen/view.php?id='.$id);}
 $pdo->beginTransaction();try{$q=$pdo->prepare("UPDATE grievances SET status='Reopened' WHERE id=? AND citizen_id=? AND status='Resolved'");$q->execute([$id,$u['id']]);if(!$q->rowCount())throw new RuntimeException();record_history($pdo,$id,'Resolved','Reopened',$u['id'],'Reopening requested: '.$reason);$q=$pdo->prepare('INSERT INTO notifications(user_id,grievance_id,message) SELECT id,?,? FROM users WHERE department_id=? AND role_id=(SELECT id FROM roles WHERE name="department_admin") AND is_active=1');$q->execute([$id,'Citizen requested reopening of '.$item['tracking_number'].'.',$item['department_id']]);$pdo->commit();flash('Reopening request recorded for department review.');}catch(Throwable $e){$pdo->rollBack();flash('Could not record the reopening request.');}redirect('citizen/view.php?id='.$id);
}
$q=$pdo->prepare('SELECT g.*,d.name department,c.name category FROM grievances g JOIN departments d ON d.id=g.department_id JOIN categories c ON c.id=g.category_id WHERE g.id=? AND g.citizen_id=?');$q->execute([$id,$u['id']]);$g=$q->fetch();if(!$g){http_response_code(404);exit('Grievance not found.');}
$q=$pdo->prepare('SELECT h.*,u.full_name FROM grievance_history h JOIN users u ON u.id=h.updated_by WHERE grievance_id=? AND is_public=1 ORDER BY created_at DESC');$q->execute([$id]);$history=$q->fetchAll();$q=$pdo->prepare('SELECT COUNT(*) FROM feedback WHERE grievance_id=?');$q->execute([$id]);$hasFeedback=(bool)$q->fetchColumn();$pageTitle='Grievance details';require '../includes/header.php';?>
<h1><?=e($g['title'])?></h1><section class="panel"><p><b>Tracking ID:</b> <?=e($g['tracking_number'])?></p><p><b>Status:</b> <?=e($g['status'])?></p><p><b>Department / category:</b> <?=e($g['department'])?> / <?=e($g['category'])?></p><p><b>Location:</b> <?=e($g['location'])?></p><p><?=nl2br(e($g['description']))?></p><?php if($g['resolution_details']):?><h2>Resolution</h2><p><?=nl2br(e($g['resolution_details']))?></p><?php endif?><?php if($g['rejection_reason']):?><p><b>Reason:</b> <?=nl2br(e($g['rejection_reason']))?></p><?php endif?><p><a href="<?=e(url('public/download.php?id='.$id))?>">Download supporting document</a></p></section>
<section class="panel"><h2>Status history</h2><?php foreach($history as $h):?><article class="card"><b><?=e($h['new_status'])?></b> · <?=e($h['created_at'])?><p><?=e($h['remarks'])?></p></article><?php endforeach?></section>
<?php if($g['status']==='Resolved'&&!$hasFeedback):?><section class="panel"><h2>Feedback</h2><form method="post" action="<?=e(url('citizen/feedback.php'))?>"><?=csrf_field()?><input type="hidden" name="grievance_id" value="<?=$id?>"><label>Rating (1 to 5)</label><select name="rating" required><?php for($i=1;$i<=5;$i++):?><option value="<?=$i?>"><?=$i?></option><?php endfor?></select><label>Comments</label><textarea name="comments" maxlength="2000"></textarea><button>Send feedback</button></form></section><section class="panel"><h2>Request reopening</h2><p>Provide a reason for the department to review the resolution again.</p><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="reopen"><input type="hidden" name="id" value="<?=$id?>"><label>Reason (at least 10 characters)</label><textarea name="reason" minlength="10" required></textarea><button>Request reopening</button></form></section><?php endif?><?php require '../includes/footer.php';?>
